def solve_magic_sequence(n):
    # x[0], x[1], ..., x[n-1]
    # Constraints:
    # 1. sum(x) = n
    # 2. sum(i * x[i]) = n
    # 3. x[i] = count of i in x
    # 4. x[11] = 0, x[12] = 0

    import itertools

    # We can use backtracking or a constraint solver.
    # Since n=14 is small, let's try backtracking.

    x = [0] * n
    x[11] = 0
    x[12] = 0

    def is_consistent(current_x, length):
        # Check if the counts so far are consistent
        for i in range(length):
            count = current_x.count(i)
            if current_x[i] != 0 and current_x[i] != count:
                return False
        # Also check if the remaining counts could potentially be satisfied
        # This is a bit more complex, but let's start simple.
        return True

    def backtrack(idx, current_x):
        if idx == n:
            # Final check
            for i in range(n):
                if current_x.count(i) != current_x[i]:
                    return None
            return current_x

        if idx == 11 or idx == 12:
            return backtrack(idx + 1, current_x)

        # Try values for x[idx]
        # The sum of x[i] is n, so x[idx] <= n
        for val in range(n):
            current_x[idx] = val
            # Optimization: check if sum exceeds n
            if sum(current_x) > n:
                continue

            # Optimization: check if sum(i*x[i]) exceeds n
            if sum(i * current_x[i] for i in range(idx + 1)) > n:
                continue

            res = backtrack(idx + 1, current_x)
            if res:
                return res

        current_x[idx] = 0
        return None

    return backtrack(0, x)

